use vstd::prelude::*;

verus! {

/// prefix_sum(k) = Σ_{i=1..k} a[i], where
/// a[i] = -i if i odd, +i if i even.
/// Closed‐form: if k even, k/2; if k odd, −(k+1)/2.
spec fn prefix_sum(k: nat) -> int
    decreases k,
{
    if k % 2 == 0 {
        k / 2
    } else {
        -((k + 1) / 2)
    }
}

/// Given a vector of queries (l, r) with 1 ≤ l ≤ r,
/// returns for each query the sum a[l] + … + a[r].
/// Equivalently prefix_sum(r) − prefix_sum(l − 1).
fn solve(queries: Vec<(i8, i8)>) -> Vec<i8>
    requires
        // All queries satisfy 1 ≤ l ≤ r
        forall |idx: usize|
            idx < queries@.len() ==>
                let pair = queries@.index(idx);
                1 <= pair.0 && pair.0 <= pair.1,
    ensures
        // Same number of answers as queries
        result@.len() == queries@.len(),
    ensures
        // For each query, result[idx] = prefix_sum(r) − prefix_sum(l−1)
        forall |idx: usize|
            idx < result@.len() ==>
                let pair = queries@.index(idx);
                let l = pair.0;
                let r = pair.1;
                result@.index(idx) as int
                    ==
                prefix_sum((r as int) as nat)
                    -
                prefix_sum(((l as int) - 1) as nat)
{
    let mut res: Vec<i8> = Vec::new();
    let n = queries.len();
    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            res@.len() == i,
            forall |j: usize|
                j < i ==>
                    let pair = queries@.index(j);
                    let l_j = pair.0;
                    let r_j = pair.1;
                    res@.index(j) as int
                        ==
                    prefix_sum((r_j as int) as nat)
                        -
                    prefix_sum(((l_j as int) - 1) as nat),
        decreases n - i,
    {
        let (l, r) = queries[i];
        // compute prefix_sum(r)
        let r_i16 = r as i16;
        let ps_r = if r_i16 % 2 == 0 {
            r_i16 / 2
        } else {
            -((r_i16 + 1) / 2)
        };
        // compute prefix_sum(l - 1)
        let l1_i16 = (l as i16) - 1;
        let ps_l1 = if l1_i16 % 2 == 0 {
            l1_i16 / 2
        } else {
            -((l1_i16 + 1) / 2)
        };
        // result is ps_r - ps_l1, fits in i8
        let sum_i8 = (ps_r - ps_l1) as i8;
        res.push(sum_i8);
        i = i + 1;
    }
    res
}

}

fn main() {
    // example usage
    let qs = vec![(1, 4), (2, 5), (3, 3)];
    let ans = solve(qs);
    assert!(ans == vec![(-1 + 2 - 3 + 4), (2 - 3 + 4 - 5), -3]);
}